// CSD_RATIONALE_BEGIN
// Single-final-span CSD for grade-school symbolic math.
//
// Root cause analysis of prior failures:
// 1. SEMANTIC WRONG (41/49): Model writes partial sub-expressions as
//    multiple intermediate spans. The evaluator extracts the LAST span,
//    which is a partial computation (e.g. <<n2 * 2>>) instead of the
//    complete final formula (e.g. <<int(n - (n_1+n_2) - 2*n_2)>>).
// 2. UNCLOSED (6/49): Model enters a constrained span near end of budget
//    and cannot close it. The `!!!!` output suggests unconstrained
//    repetition loops before the final `<<`, consuming budget wastefully.
//
// Fixes applied:
// (a) Guidance: Strongly discourage intermediate `<< >>` spans. Tell the
//     model to write ALL reasoning in plain text and produce exactly ONE
//     final span with the complete formula.
// (b) Repetition detection: After each unconstrained token, check if it
//     has appeared more than 30 times in generated. If so, break early
//     to stop `!!!!` runaway before the final span budget is consumed.
// (c) Post-loop cleanup: If budget exhausts while inside an open span,
//     RollbackConstrainedToComplete rolls back to the longest valid
//     complete constrained prefix, then CloseConstrainedSpan closes it —
//     producing a valid shorter span instead of an unclosed one.
// (d) No minSpanTokens gate: Attempt 2's 3-token minimum caused dead-end
//     loops. With explicit guidance, the model should write a full formula.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// parser_validity: `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`
//
//   Unconstrained branch: while !insideConstrainedOut the implication is
//   vacuous. When RenderedEndsWith(generated,"<<") fires we set
//   currentConstrainedOut := [] and parser.IsValidPrefix([]) holds by
//   the method precondition `parser.IsValidPrefix([])`.
//
//   Complete-prefix branch: CloseConstrainedSpan sets insideConstrainedOut
//   := false, making the implication vacuously true, and clears
//   currentConstrainedOut to [].
//
//   Constrained-generation branch: AdaptiveConstrainedStep returns either
//   eosToken or a token t such that parser.IsValidPrefix(currentConstrainedOut
//   + [t]) holds (hard parser mask guarantees this). On EOS we break
//   (implication vacuously maintained because we exit with insideConstrainedOut
//   still true but we do not append an invalid token). AppendConstrainedToken
//   extends currentConstrainedOut by exactly t, preserving IsValidPrefix.
//
//   Post-loop: RollbackConstrainedToComplete postcondition guarantees
//   parser.IsValidPrefix on the returned currentOut. CloseConstrainedSpan
//   then sets insideConstrainedOut := false (implication vacuously true).
//
// progress: `|generated| <= |generatedPrefix| + steps`
//
//   Unconstrained branch: steps += 1; generated grows by at most 1 token
//   (EOS is not appended; a "<<" token is exactly 1 visible token). The
//   repetition-break path also only appended one token before breaking.
//   Bound preserved.
//
//   Complete-prefix branch: steps += 1; CloseConstrainedSpan appends at
//   most 1 visible delimiter (">>"). Visible growth = 1 = steps growth.
//   Bound preserved.
//
//   Constrained-generation branch: steps += 1; AdaptiveConstrainedStep
//   costs exactly 1 step. AppendConstrainedToken appends at most 1
//   expression token. Visible growth ≤ 1 = steps growth. Bound preserved.
//
//   Post-loop rollback: RollbackConstrainedToComplete can only reduce
//   |generated| (stable prefix + shorter currentOut ≤ old generated).
//   steps is unchanged. CloseConstrainedSpan adds 1 token and we guard
//   `steps < maxSteps` before calling, so after the call steps ≤ maxSteps.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance := "Solve step by step in plain prose. Do NOT use << >> delimiters during your reasoning — write all intermediate steps as plain text. Only at the very end write exactly: The final answer is <<FORMULA>> where FORMULA is a single complete Python arithmetic expression for the final numeric answer. Use ONLY the numeric variable names that appear in curly braces in the problem (e.g. n, n1, w1, price). Do NOT include string-type variables (unit labels, currency symbols) in FORMULA. Your FORMULA must combine ALL necessary variables into ONE complete expression, not just an intermediate sub-result.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    // Repetition guard: break if this token has become a runaway loop
    var cnt := CSDHelpers.CountTokenOccurrences(generated, next);
    if cnt > 30 {
      break;
    }
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    var ag, ai, ac := helpers.AppendConstrainedToken(
      lm, parser, generated, currentConstrainedOut, next
    );
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
  }
}

// Post-loop cleanup: if we exited while inside an open span (EOS or budget
// exhausted), roll back to the longest valid complete prefix and close it.
if insideConstrainedOut {
  var rg, rc := helpers.RollbackConstrainedToComplete(
    parser, generated, currentConstrainedOut
  );
  generated := rg;
  currentConstrainedOut := rc;
  if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  }
}

cost := steps;

